//	JOIN crew_members cm ON cm.id = te.crew_member_id
//	LEFT JOIN users u ON u.id = cm.user_id
//	WHERE te.trip_id = $1
//	ORDER BY te.created_at, te.id
func (q *Queries) ListTripEnrollments(ctx context.Context, tripID int64) ([]ListTripEnrollmentsRow, error) {
	rows, err := q.db.QueryContext(ctx, listTripEnrollments, tripID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListTripEnrollmentsRow
	for rows.Next() {
		var i ListTripEnrollmentsRow
		if err := rows.Scan(
			&i.ID,
			&i.TripID,
			&i.CrewMemberID,
			&i.UserID,
			&i.Note,
			&i.Status,
			&i.PaymentStatus,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.PersonName,
			&i.PersonEmail,
			&i.AccountEmail,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

