const lockTripForSignUp = `-- name: LockTripForSignUp :one
SELECT t.id, t.status, (t.enroll_token IS NOT NULL)::BOOLEAN AS open, t.enroll_token, t.max_crew, t.sign_up_deadline,
       (t.published_at IS NOT NULL AND EXISTS (
           SELECT 1 FROM cruises c WHERE c.id = t.cruise_id AND c.published_at IS NOT NULL))::BOOLEAN AS published
FROM trips t
WHERE t.id = $1
FOR NO KEY UPDATE OF t
`

type LockTripForSignUpRow struct {
	ID             int64            `json:"id"`
	Status         TripStatus       `json:"status"`
	Open           bool             `json:"open"`
	EnrollToken    types.NullString `json:"enroll_token"`
	MaxCrew        types.NullInt64  `json:"max_crew"`
	SignUpDeadline types.NullString `json:"sign_up_deadline"`
	Published      bool             `json:"published"`
}

// Locks one trip for the rest of a sign-up or accept transaction, so the leg
// cannot be cancelled, closed, completed or deleted between the check and
// the write, and concurrent sign-ups and accepts of the leg take its places
// one at a time. FOR NO KEY UPDATE still lets foreign-key checks (KEY SHARE)
// through. open is true while the leg's sign-ups are switched on (it has an
// enroll token); enroll_token is the current share token, so a share-link
// sign-up can check the presented token still holds. sign_up_deadline is the
// last day it takes them. published is true while the trip and its cruise
// are both published: a hidden leg takes no sign-ups. No row when the trip
// does not exist.
//
//	SELECT t.id, t.status, (t.enroll_token IS NOT NULL)::BOOLEAN AS open, t.enroll_token, t.max_crew, t.sign_up_deadline,
//	       (t.published_at IS NOT NULL AND EXISTS (
//	           SELECT 1 FROM cruises c WHERE c.id = t.cruise_id AND c.published_at IS NOT NULL))::BOOLEAN AS published
//	FROM trips t
//	WHERE t.id = $1
//	FOR NO KEY UPDATE OF t
func (q *Queries) LockTripForSignUp(ctx context.Context, id int64) (LockTripForSignUpRow, error) {
	row := q.db.QueryRowContext(ctx, lockTripForSignUp, id)
	var i LockTripForSignUpRow
	err := row.Scan(
		&i.ID,
		&i.Status,
		&i.Open,
		&i.EnrollToken,
		&i.MaxCrew,
		&i.SignUpDeadline,
		&i.Published,
	)
	return i, err
}

const mergeSharedTripEnrollmentPayments = `-- name: MergeSharedTripEnrollmentPayments :exec
UPDATE trip_enrollments w SET
    payment_status = (ARRAY['unpaid', 'deposit', 'paid'])[GREATEST(
        COALESCE(array_position(ARRAY['unpaid', 'deposit', 'paid'], k.payment_status), 1),
        COALESCE(array_position(ARRAY['unpaid', 'deposit', 'paid'], d.payment_status), 1))],
    updated_at = CURRENT_TIMESTAMP
FROM trip_enrollments k
JOIN trip_enrollments d ON d.trip_id = k.trip_id
WHERE k.crew_member_id = $1::BIGINT
  AND d.crew_member_id = $2::BIGINT
  AND w.id IN (k.id, d.id)
  AND k.payment_status <> d.payment_status
`

type MergeSharedTripEnrollmentPaymentsParams struct {
	KeptID      int64 `json:"kept_id"`
	DuplicateID int64 `json:"duplicate_id"`
}

// On a leg both people signed up for, both sign-ups take the more advanced
// payment status of the two (unpaid < deposit < paid), so the one a merge
// keeps (DeleteSharedTripEnrollments) loses no recorded payment.
//
//	UPDATE trip_enrollments w SET
//	    payment_status = (ARRAY['unpaid', 'deposit', 'paid'])[GREATEST(
//	        COALESCE(array_position(ARRAY['unpaid', 'deposit', 'paid'], k.payment_status), 1),
//	        COALESCE(array_position(ARRAY['unpaid', 'deposit', 'paid'], d.payment_status), 1))],
//	    updated_at = CURRENT_TIMESTAMP
//	FROM trip_enrollments k
//	JOIN trip_enrollments d ON d.trip_id = k.trip_id
//	WHERE k.crew_member_id = $1::BIGINT
//	  AND d.crew_member_id = $2::BIGINT
//	  AND w.id IN (k.id, d.id)
//	  AND k.payment_status <> d.payment_status
func (q *Queries) MergeSharedTripEnrollmentPayments(ctx context.Context, arg MergeSharedTripEnrollmentPaymentsParams) error {
	_, err := q.db.ExecContext(ctx, mergeSharedTripEnrollmentPayments, arg.KeptID, arg.DuplicateID)
	return err
}

